import java.util.Comparator

data class Person(val name: String, val age: Int)

class PersonService {
    fun sortGroups(groups: List<List<Person>>) = groups.map { group ->
        group.sortedWith(Comparator.comparing(Person::name)) // bad: Comparator recreated per group
    }
}

import java.util.Comparator

data class Person(val name: String, val age: Int)

class PersonSorter {
    companion object {
        private val BY_NAME = Comparator.comparing(Person::name) // ok: created once
    }
    fun sort(people: List<Person>) = people.sortedWith(BY_NAME)
}
